def rebalance(questions):
    for i, q in enumerate(questions):
        target = i % 4
        a = q["ans"]
        if a != target:
            q["opts"][a], q["opts"][target] = q["opts"][target], q["opts"][a]
            q["ans"] = target
    return questions


def main():
    root = os.getcwd()
    with io.open(os.path.join(root, INIT), encoding="utf-8") as f:
        init = f.read()
    with io.open(os.path.join(root, DATA_PATH), encoding="utf-8") as f:
        data = json.load(f)

    if len(data["taxes_invoicing"]["lessons"]) == 9 and len(data["taxes_invoicing"]["questions"]) >= 35:
        print("Already applied. Nothing to do.")
        return
    if '"3.91.0"' not in init:
        sys.exit("ABORT: not at v3.91.0.")

    problems = []
    if len(LESSONS) != 9:
        problems.append(f"  {len(LESSONS)} lessons (want 9)")
    short = [f"{l['title'][:40]} ({len(l['html'])})" for l in LESSONS if len(l["html"]) < 2500]
    if short:
        problems.append(f"  below manual depth: {short}")
    if len(NEW_QUESTIONS) != 23:
        problems.append(f"  {len(NEW_QUESTIONS)} new questions (want 23)")
    for q in NEW_QUESTIONS:
        if len(q["opts"]) != 4 or not (0 <= q["ans"] <= 3):
            problems.append(f"  malformed '{q['q'][:40]}'")
    if "ERPNext" in json.dumps({"l": LESSONS, "q": NEW_QUESTIONS}):
        problems.append("  ERPNext branding leakage")
    if problems:
        print("ABORT — not clean:")
        print("\n".join(problems))
        sys.exit(1)

    merged = rebalance(data["taxes_invoicing"]["questions"] + NEW_QUESTIONS)
    dist = {c: sum(1 for q in merged if q["ans"] == i) for i, c in enumerate("ABCD")}
    if max(dist.values()) > 10:
        print(f"ABORT — spread failed: {dist}")
        sys.exit(1)

    total = sum(len(l["html"]) for l in LESSONS)
    old_total = sum(len(l["html"]) for l in data["taxes_invoicing"]["lessons"])
    print(f"Selling 6: {len(data['taxes_invoicing']['lessons'])} lessons ({old_total:,} chars) -> 9 chapters ({total:,} chars, {total/old_total:.1f}x); bank -> {len(merged)}, spread {dist}")

    if CHECK_ONLY:
        print("--check given; no files written.")
        return

    data["taxes_invoicing"]["lessons"] = LESSONS
    data["taxes_invoicing"]["questions"] = merged
    with io.open(os.path.join(root, DATA_PATH), "w", encoding="utf-8") as f:
        json.dump(data, f, indent=1, ensure_ascii=False)
        f.write("\n")
    with io.open(os.path.join(root, INIT), "w", encoding="utf-8") as f:
        f.write(init.replace('"3.91.0"', '"3.92.0"'))
    print("  data: Selling 6 -> 9 manual chapters, 35-question bank")
    print("wrote __init__.py -> 3.92.0")


if __name__ == "__main__":
    main()
